def faq():
 qa=[('실제 변호사 검색이 가능한가요?','현재 제공하는 파일은 고객 검토용 디자인 시안입니다. 표시된 변호사 프로필은 모두 가상 예시이며 실제 변호사 검색·자격 검증은 운영 데이터 연결 이후 가능합니다.'),('Google Blogger 글은 자동으로 들어오나요?','Blogger 공개 RSS·Atom 피드 또는 승인된 API로 연동할 수 있으나 이 정적 시안에는 서버 수집 기능이 없습니다. 블로그 URL 연결과 미리보기를 먼저 제공합니다.'),('YouTube 영상은 바로 재생되나요?','공개 영상의 유효한 ID를 입력하면 YouTube의 개인정보 보호 강화 임베드로 재생할 수 있습니다. 실제 재생은 YouTube 정책과 브라우저 네트워크에 따라 달라집니다.'),('로이고 판에서 상담을 결제할 수 있나요?','현재 시안에는 실결제·예약 기능이 없습니다. 문의 흐름만 제공합니다.'),('변호사 자격은 어떻게 확인하나요?','운영 시 변호사 자격 확인, 소속 기관 및 광고 관련 기준 준수 여부 확인 절차가 필요합니다.'),('구독료는 확정됐나요?','표시된 금액은 사업 제안 요금이며 운영 확정가가 아닙니다.'),('한영 번역은 어떻게 작동하나요?','기본 메뉴와 주요 텍스트는 내장 영문 번역을 제공하며, 구글 번역 위젯 사용 가능 시 전체 페이지를 번역합니다.')]
 return top('faq')+f'<section class="shell block"><div class="faq-list">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in qa)+'</div></section>'

def about():return top('about')+f'''<section class="shell block"><div class="split"><div>{small('LEGAL CONTENT × EXPERT NETWORK','LEGAL CONTENT × EXPERT NETWORK')}<h2>법률 전문가의 지식이<br>더 많은 사람에게 닿도록.</h2><p>LAWYGO PAN은 전문가 검색, 글과 영상 큐레이션, 상담 문의 동선을 잇는 서비스 콘셉트입니다. 기존 LAWYGO의 경제·법률 정보저널, 백과, 문서 도구, 송무 관리 서비스와 연계되는 브랜드 구조로 설계했습니다.</p>{cta('전문가 페이지 만들기','blog-builder')}</div>{img('books','feature-shot')}</div><div class="topic-grid cols4">{''.join(f'<article><h3>{t}</h3><p>{d}</p></article>' for t,d in [('JOURNAL','미국·한국 경제·제도 변화의 법률적 인사이트'),('WIKI','법령과 판례정보를 연결하는 정보백과'),('NOTE','서류와 판례를 분석하는 실무 도구'),('PRO','사건·기일·문서를 관리하는 송무 프로그램')])}</div></section>'''

