def legal(slug):
 paragraphs=['이 문서는 법률 검토를 위한 시안이며, 실제 서비스를 시작하기 전에 운영사·수탁사·개인정보 처리 절차와 책임 범위를 확정하여 수정해야 합니다.','서비스 이용자는 제공되는 일반 법률정보가 개별 사건의 법률 자문이 아니라는 점을 확인해야 합니다. 구체적인 문제는 변호사에게 상담하시기 바랍니다.','프로필·콘텐츠·영상의 권리는 해당 작성자에게 있으며, 외부 콘텐츠는 원문 링크와 허용된 임베드를 중심으로 노출해야 합니다.','고객 문의 데이터의 저장, 보존 기간, 국외 이전, 수탁사 및 열람 권한 등의 실제 정책은 정식 오픈 전에 공개해야 합니다.']
 return top(slug)+'<section class="shell article-shell"><div class="notice"><strong>운영 전 검토 필수</strong> · 현재 문서는 확정된 계약 또는 개인정보처리방침이 아닙니다.</div><div class="article-body">'+''.join('<h2>제'+str(i)+'조 · '+t+'</h2><p>'+p+'</p>' for i,(t,p) in enumerate(zip(['안내 목적','이용 범위','콘텐츠 및 저작권','개인정보·보안'],paragraphs),1))+'</div></section>'

